def handle(app, svc):
    """Calloway partner handler (API v2).

    Maps the partner's outcome to our action, and applies the
    network-wide self-employment referral rule (spec section 4).
    """
    res = svc.apply(app) or {}
    # v2 shape: {"api_version": 2, "result": {"outcome": ..., "credit_limit": int}}
    result = res.get("result") or {}
    outcome = result.get("outcome")
    credit_limit = result.get("credit_limit") or 0

    if outcome == "approved":
        action = "issue"
        limit = int(credit_limit)
    elif outcome == "declined":
        action = "decline"
        limit = 0
    else:
        # manual_review (or any unexpected value): not a decision,
        # so it stays in the manual review queue (spec section 3).
        action = "queue_review"
        limit = 0

    # Network-wide referral rule (spec section 4): a self_employed
    # applicant whose requested_limit is above 7000 must go to manual
    # review instead of being issued. A decline stays a decline.
    if action == "issue":
        employment = app.get("employment")
        requested = app.get("requested_limit")
        try:
            requested = int(requested)
        except (TypeError, ValueError):
            requested = None
        if employment == "self_employed" and requested is not None and requested > 7000:
            action = "queue_review"
            limit = 0

    return {"action": action, "limit": limit}
